insert into banco.ambito(codigo,nombre) values ('CU','Cuba') on conflict do nothing;
insert into banco.categoria(clave,nombre,fase,descripcion,orden) values ('transicion','Transición Democrática','Fase 1 — Hoja de Ruta','Propuestas sobre cómo se llega del sistema actual a la democracia: gobierno provisional, plazos, secuencia.',1),('constitucion','Proceso Constituyente','Fase 2 — Constitución','Propuestas sobre el contenido de la futura Constitución: derechos, poderes, garantías, soberanía.',2),('modelo_pais','Plataforma de Gobierno','Fase 3 — Modelo de País','Propuestas sobre el tipo de país a construir: modelo económico, social, institucional de largo plazo.',3),('sistema_electoral','Sistema Electoral','Fase 4 — Candidaturas','Propuestas sobre elecciones, partidos, voto, representación.',4),('reconstruccion','Reconstrucción Nacional','Módulo Especial','Propuestas sobre planes de reconstrucción, capital, marcos legales y compromisos verificables.',5),('educacion','Educación','Fase 3 — Modelo de País','Propuestas sobre el sistema educativo: formación cívica y ética, universidades, enseñanza de la memoria histórica, formación profesional.',6),('economia','Economía','Fase 3 — Modelo de País','Propuestas sobre el modelo y la política económica: propiedad, empresa, inversión, comercio, finanzas, impuestos, consumidores.',7),('trabajo','Trabajo y Seguridad Social','Fase 3 — Modelo de País','Propuestas sobre derechos laborales, sindicatos, empleo, salarios, pensiones y seguridad social.',8),('salud','Salud','Fase 3 — Modelo de País','Propuestas sobre el sistema de salud, acceso, calidad y financiamiento.',9),('medio_ambiente','Medio Ambiente','Fase 3 — Modelo de País','Propuestas sobre protección del hábitat, agua, aire, mar, especies, pesca, educación ambiental y tratados climáticos.',10),('sociedad_civil','Sociedad Civil','Fase 3 — Modelo de País','Propuestas sobre asociaciones, participación ciudadana y fortalecimiento de la sociedad civil.',11),('derechos','Derechos y Libertades','Fase 2 — Constitución','Propuestas sobre derechos humanos, garantías y libertades fundamentales.',12),('familia','Familia, Niñez y Juventud','Fase 3 — Modelo de País','Propuestas sobre la familia, la niñez, la adolescencia y la juventud.',13),('tercera_edad','Tercera Edad','Fase 3 — Modelo de País','Propuestas sobre las personas mayores: pensiones, cuidado, salud y protección.',14),('vivienda','Vivienda y Urbanismo','Fase 3 — Modelo de País','Propuestas sobre vivienda, construcción, urbanismo y hábitat.',15),('genero','Género e Igualdad','Fase 3 — Modelo de País','Propuestas sobre igualdad de género, paridad y prevención de la violencia de género.',16),('animales','Protección Animal y Biodiversidad','Fase 3 — Modelo de País','Propuestas sobre bienestar y derechos de los animales, especies y biodiversidad.',17),('alimentacion','Alimentación y Agro','Fase 3 — Modelo de País','Propuestas sobre soberanía alimentaria, agricultura, ganadería, pesca y derecho a la alimentación.',18) on conflict do nothing;
insert into banco.consolidada(id,categoria_clave,titulo,texto,nota,orden) values ('presos-politicos','transicion','Liberación de todas las personas presas por motivos políticos','Liberar de inmediato a todas las personas detenidas, sancionadas o encarceladas por motivos políticos o de conciencia.','Las fuentes coinciden en liberar a todas las personas presas por motivos políticos. Difieren en el procedimiento: la mayoría la exige de inmediato o por amnistía; una fuente la vincula a un referendo.',1),('despenalizacion-disenso','transicion','Despenalizar el disenso y la opinión política','Abolir la criminalización de la opinión política y detener el ciclo de penalización, castigo y exclusión de la diferencia y de los diferentes.',null,2),('amnistia-reciproca','transicion','Amnistía recíproca, general y plena, salvo crímenes graves','Favorecer una amnistía recíproca, general y plena, que alcance también a autoridades, funcionarios y agentes que persiguieron a opositores, excepto a quienes hayan cometido crímenes de lesa humanidad o violaciones graves de derechos humanos, desde cualquiera de las partes en conflicto.','Otras fuentes piden el fin de la impunidad y procesos judiciales para los responsables. Ver la cuestión sobre qué hacer con los responsables de la represión.',3),('legalizacion-organizaciones','transicion','Legalizar los partidos y las organizaciones independientes','Legalizar de inmediato a todos los partidos políticos y a las organizaciones independientes de la sociedad civil, incluidos los grupos de derechos humanos, con plena libertad de acción y sin acoso.',null,4),('gobierno-transicion','transicion','Gobierno provisional de duración limitada que conduzca a elecciones libres','Instalar un gobierno de transición, provisional y de duración limitada, que restituya las libertades civiles, políticas y económicas y conduzca a elecciones libres. Solo se acatará como definitivo el gobierno que salga de la voluntad soberana del pueblo.',null,5),('gobierno-reconciliacion-paritario','transicion','Gobierno de Reconciliación y Unidad Nacional, mitad oposición y mitad Asamblea actual','Formar un Gobierno de Reconciliación y Unidad Nacional con un 50 % de miembros propuestos por el Comité Gestor del referendo del programa «Todos Cubanos» y un 50 % propuestos por la Asamblea Nacional del Poder Popular.',null,6),('transicion-por-fases','transicion','Plan de transición en cuatro fases','Organizar la transición en cuatro fases: liberación, estabilización, reconstrucción y democratización del país.',null,7),('elecciones-antes-de-constituyente','transicion','Primero elecciones libres; el nuevo parlamento gobierna durante la etapa constituyente','En una etapa preliminar, elegir en elecciones libres un nuevo parlamento y un presidente de la República, que gobernarán mientras dure la etapa constituyente.',null,8),('transicion-pacifica','transicion','Transición pacífica, sin violencia política','Trabajar por una transición absolutamente pacífica, ordenada y eficaz hacia un Estado democrático de derecho, desterrando para siempre la violencia de las querellas políticas, también la que se ejerce desde el Estado.',null,9),('transicion-inclusiva','transicion','Una transición que incluya a todos los cubanos, sin revancha','Garantizar que todos los cubanos participen en la transición, sin exclusiones de clase alguna y sin odios ni revanchas, incluidos quienes hoy respaldan al Gobierno.',null,10),('resistencia-civica','transicion','Movilización ciudadana no violenta','Una estrategia de movilización ciudadana sostenida, organizada y no violenta como eje para lograr la transición: protestas públicas, cacerolazos, boicots, plantones, paros estudiantiles, campañas informativas y rechazo masivo a los procesos sin garantías democráticas.',null,11),('unidad-de-la-oposicion','transicion','Foro permanente de concertación entre organizaciones','Crear un foro permanente en el que las organizaciones, conservando su identidad, debatan, diseñen estrategias comunes y elaboren propuestas políticas conjuntas.',null,12),('dialogo-nacional','transicion','Diálogo nacional entre todos los cubanos','Un diálogo nacional en el que estén representadas todas las tendencias políticas, la sociedad civil de la isla y de la diáspora y el gobierno, para hallar una solución cubana a la crisis cubana y llegar a un nuevo pacto social.',null,13),('apertura-acordada','transicion','Apertura acordada en dos procesos paralelos: entre cubanos y entre Cuba y Estados Unidos','Lograr una apertura acordada mediante una negociación política entre la sociedad civil y política de la isla y la diáspora y el Gobierno de Cuba, en paralelo con un proceso entre Cuba y Estados Unidos, comprometida con reducir el sufrimiento del pueblo y con la libertad, los derechos humanos, la democracia y el imperio de la ley.',null,14),('consulta-popular','transicion','Consulta popular vinculante para decidir el cambio','Que el pueblo decida el cambio en una consulta popular vinculante: referendo, plebiscito o elecciones generales.',null,15),('de-la-ley-a-la-ley','transicion','Transición ordenada «de la ley a la ley», sin ruptura institucional','Una transición ordenada mediante el derecho: un proceso de transformaciones jurídicas que, desde la ley y sin ruptura institucional, garantice los derechos humanos y la participación de todos los cubanos en igualdad de condiciones.',null,16),('presion-externa-sanciones','transicion','Presión internacional y sanciones contra las estructuras del Gobierno','Endurecer las sanciones contra las estructuras del Gobierno y coordinar una presión internacional y económica hasta que haya apertura democrática.',null,17),('normalizacion-cuba-eeuu','transicion','Normalizar las relaciones con Estados Unidos y poner fin al embargo','Construir relaciones positivas con Estados Unidos desde el respeto a la soberanía de ambos pueblos, mediante un diálogo entre los dos Estados que incluya a la sociedad civil y a la oposición democrática, con el fin del embargo como pilar.','Las razones difieren: una fuente lo plantea como parte de una apertura acordada; otra sostiene que el embargo no funciona y daña al pueblo que se quiere liberar.',18),('apoyo-internacional','transicion','Acompañamiento internacional de la transición','Pedir a la comunidad internacional que respalde el derecho de los cubanos a decidir su futuro democrático, exija garantías electorales y acompañe la transición con mediación, asesoría y verificación.',null,19),('ayuda-exterior-legitima','transicion','Criterios para aceptar ayuda exterior','Considerar legítima la ayuda exterior a la sociedad civil salvo la que provenga de actividades ilícitas o del lavado de dinero, la que salga directamente de las arcas de los Estados y la que venga condicionada.',null,20),('proscripcion-comunismo','transicion','Erradicar del poder político las doctrinas comunistas y totalitarias','Desmilitarizar el país y erradicar del poder político toda doctrina antidemocrática, comunista o totalitaria.',null,21),('comision-verdad','transicion','Comisión de la Verdad independiente','Crear por ley una Comisión de Verdad, Justicia, Reconciliación y Memoria Histórica: oficial, independiente, no judicial y de duración limitada, que esclarezca los hechos, causas y consecuencias de las violaciones de derechos humanos y entregue un informe a la sociedad.',null,22),('justicia-transicional','transicion','Justicia transicional, sin impunidad y sin venganza','Aprobar una ley marco de justicia transicional que equilibre verdad, justicia, reparación y reconciliación, con un sistema de justicia restaurativo e integral que acabe con la impunidad por crímenes de lesa humanidad sin convertirse en venganza política.',null,23),('reparacion-victimas','transicion','Reparación integral a las víctimas','Una ley y un programa de reparación integral a las víctimas del totalitarismo, en especial a quienes estuvieron presos por razones políticas, de identidad, ideológicas o de conciencia: indemnización, rehabilitación, restitución, búsqueda de desaparecidos, disculpas públicas y garantías de no repetición.',null,24),('memoria-historica','transicion','Memoria histórica plural, documentada y enseñada','Recuperar, documentar y enseñar la memoria histórica como garantía para no retroceder, promoviendo una memoria plural, como experiencia y no como nuevo canon, mediante investigaciones y exposiciones libres.',null,25),('reconciliacion','transicion','Reconciliación nacional guiada por el diálogo','Un proceso de reconciliación nacional basado en la paz, la justicia y la transparencia, guiado por el diálogo, que combine memoria, justicia restaurativa y reparación, y permita sanar, reconstruir y mirar adelante.',null,26),('lustracion','transicion','Ley de lustración','Aprobar una Ley de Lustración que tenga en cuenta las características propias de Cuba.','Lustración: revisión del pasado de quienes aspiran a cargos públicos, para limitar el acceso de quienes participaron en la represión. La fuente no detalla su alcance.',27),('asamblea-constituyente','constitucion','Una Asamblea Constituyente libremente elegida para una nueva Constitución','Convocar una Asamblea Constituyente libremente elegida por el pueblo, con la participación de todos los sectores y posiciones políticas, que redacte una nueva Constitución para someterla a referendo.',null,28),('proceso-constituyente','constitucion','Reglas claras y participación ciudadana en el proceso constituyente','Regular por ley el proceso constituyente para que la ciudadanía participe en la redacción de la nueva Constitución, y no solo en el debate de un proyecto ya elaborado: que cualquier cubano pueda proponer, dar a conocer y discutir sus propuestas.',null,29),('constitucion-1940','constitucion','Restituir la Constitución de 1940','Restituir la Constitución de 1940, aprobada por una Constituyente soberana, para restablecer el hilo republicano y democrático roto en 1952 y desde 1959, y disponer de un orden legal tras la dictadura.','Las fuentes difieren en el alcance: restitución plena como orden legal, o referencia transitoria hasta una nueva Constitución.',30),('reforma-provisional-2019','constitucion','Reforma provisional de la Constitución de 2019 como puente hacia una constituyente','Aprobar una Ley Electoral Provisional y celebrar elecciones libres junto con un referendo que autorice a los diputados electos a hacer una Reforma General Provisional de la Constitución de 2019; con esas garantías, encaminar el país hacia un proceso constituyente originario.',null,31),('reforma-clausula-hacia-constituyente','constitucion','Reformar solo la cláusula de reforma para abrir paso a una Asamblea Constituyente','Modificar únicamente la cláusula de reforma de la Constitución vigente para permitir convocar una Asamblea Constituyente, mediante un proyecto de ley ante la Asamblea Nacional o por iniciativa legislativa popular, con la última palabra en referendo.',null,32),('reforma-constitucional-vigente','constitucion','Que la Asamblea Nacional elimine de la Constitución lo que impide una sociedad libre','Que la Asamblea Nacional del Poder Popular reforme la Constitución vigente para eliminar los artículos que impiden una sociedad libre y democrática, y permita el pluripartidismo, la libertad de asociación, reunión, movimiento y expresión, con acceso equitativo de la oposición a los medios.',null,33),('reforma-de-la-constitucion','constitucion','Reglas exigentes para reformar la Constitución','Que toda reforma general de la Constitución se someta a consulta ciudadana y se apruebe por mayoría absoluta, o cualificada, de los electores inscritos, y no solo de los votantes.',null,34),('estructura-nueva-constitucion','constitucion','Los derechos antes que los poderes en la nueva Constitución','Que en la nueva Constitución la parte de derechos y deberes de la persona preceda a la organización del Estado.',null,35),('preambulo-invocacion-dios','constitucion','Invocar a Dios en el preámbulo de la Constitución','Incluir en el preámbulo la invocación del favor de Dios, junto a la dignidad de la persona, el Estado de Derecho, la democracia y el protagonismo de la sociedad civil.',null,36),('elementos-a-conservar','constitucion','Conservar los aportes valiosos de la Constitución actual','Que cualquier reforma constitucional mantenga y desarrolle los elementos valiosos del texto actual: la vocación soberanista e independentista, la igualdad jurídica, el carácter social y la protección del ideario de justicia social.',null,37),('simbolos-nacionales','constitucion','Símbolos nacionales','Los símbolos nacionales son los que han presidido las luchas por la independencia y la libertad: la bandera de la estrella solitaria, el himno de Bayamo y el escudo de la palma real.',null,38),('dignidad-humana','constitucion','La dignidad de la persona como centro de la Constitución','Que la dignidad plena de toda persona sea el principio, el centro y el fin del nuevo orden jurídico: la persona vale por el simple hecho de existir y es un fin en sí misma, nunca un medio.',null,39),('soberania-popular','constitucion','La soberanía reside en el pueblo','Reconocer que la soberanía reside en el pueblo, que posee el poder constituyente y lo ejerce directamente, por asambleas constituyentes y referendos, o por medio de sus representantes, con la democracia más participativa posible.',null,40),('soberania-nacional','constitucion','Nación independiente y soberana','Afirmar la independencia nacional, la integridad territorial y la soberanía de Cuba: no ser vasallos de ninguna potencia extranjera.',null,41),('estado-de-derecho','constitucion','Estado democrático y social de derecho, con separación de poderes','Constituir a Cuba como República unitaria y Estado democrático y social de derecho, pluralista, descentralizado y con independencia entre los poderes, que ampare a los ciudadanos frente a la arbitrariedad.',null,42),('gobierno-limitado','constitucion','Un gobierno limitado a defender los derechos naturales','Un gobierno limitado, como lo concibieron los independentistas en la manigua, cuya única razón de ser sea la defensa de los derechos naturales de los cubanos.',null,43),('estado-laico','constitucion','Estado laico que respete todas las religiones','Un Estado laico, sin religión oficial, que respete los derechos de todas las religiones, de los creyentes y de los no creyentes, y que no limite ni intervenga en la misión de las iglesias.',null,44),('fin-partido-unico-dirigente','constitucion','Fin del Partido Comunista como fuerza dirigente del Estado','Eliminar el papel del Partido Comunista como fuerza única y dirigente de la sociedad y del Estado, y separar el partido de la administración.',null,45),('tribunal-constitucional','constitucion','Tribunal Constitucional independiente y supremacía de la Constitución','Crear un Tribunal Constitucional autónomo que garantice la supremacía de la Constitución y pueda anular leyes y actos del poder que la violen o vulneren los tratados de derechos humanos.',null,46),('gobierno-semiparlamentario','constitucion','Sistema de gobierno semiparlamentario con Primer Ministro','Un sistema de gobierno semiparlamentario, con un Primer Ministro como jefe de gobierno y un fuerte control del ejecutivo por instituciones estables y por la sociedad civil, para evitar el caudillismo y los populismos.',null,47),('eleccion-directa-presidente','constitucion','Presidente elegido directamente por el pueblo','Elegir al Presidente de la República por voto directo, libre y secreto, por mayoría absoluta y con segunda vuelta entre los dos más votados si nadie la alcanza.',null,48),('parlamento','constitucion','Un parlamento profesional que controle al gobierno','Un parlamento moderno, profesional y permanente, con contrapesos reales y capacidad para controlar al gobierno y fiscalizar las políticas públicas.',null,49),('parlamento-bicameral','constitucion','Parlamento de dos cámaras elegidas por voto directo','Un poder legislativo bicameral, con senadores y representantes elegidos por voto directo y secreto, renovable por mitades y revocable.',null,50),('limitacion-mandatos','constitucion','Prohibir la perpetuación en el poder','Prohibir cualquier reforma que permita o favorezca la perpetuación en el poder o el autoritarismo del ejecutivo.',null,51),('revocacion-mandato','constitucion','Revocación del mandato de todos los cargos electos','Establecer referendos revocatorios para todos los cargos públicos electos, regulando cuándo y cómo pueden convocarse.',null,52),('defensor-pueblo','constitucion','Defensor del Pueblo independiente','Crear la Defensoría del Pueblo, inspirada en el ombudsman, como garante independiente de los derechos humanos, accesible a cualquier persona en cualquier momento y con capacidad para investigar violaciones y actuar ante los tribunales.',null,53),('independencia-judicial','constitucion','Poder judicial independiente, imparcial y profesional','Organizar un poder judicial nuevo, independiente, imparcial y profesional, en el que los jueces respondan a la ley y no al partido, con duras penas y nulidad del proceso ante cualquier coacción o corrupción.','Una misma fuente propone en dos documentos fórmulas distintas para elegir las presidencias de los tribunales.',54),('seleccion-de-jueces','constitucion','Jueces seleccionados por mérito, en procesos públicos','Seleccionar jueces y magistrados con procedimientos rigurosos, públicos y transparentes, basados solo en el mérito, la integridad ética, la independencia de criterio, la formación y la experiencia.',null,55),('jueces-de-paz','constitucion','Jueces de paz elegidos en los municipios','Crear jueces de paz no profesionales, elegidos en procesos democráticos municipales, a los que las partes puedan acudir cuando no resuelvan su conflicto por negociación o mediación.',null,56),('ciudadania','constitucion','Nadie pierde la ciudadanía cubana; se admite la doble ciudadanía','Ningún cubano por nacimiento podrá ser privado de su ciudadanía, y se reconoce el derecho a tener varias ciudadanías sin perder los derechos de la cubana.',null,57),('carta-de-derechos','derechos','Una carta de derechos amplia, progresiva y directamente exigible','Garantizar el respeto pleno a los derechos humanos con un catálogo amplio de derechos individuales, sociales y de tercera y cuarta generación, directamente aplicable aunque no exista una ley que lo desarrolle, y con el régimen de garantías más amplio posible.',null,58),('pactos-ddhh','derechos','Los pactos internacionales de derechos humanos, con rango constitucional','Ratificar los Pactos Internacionales de Derechos Civiles y Políticos y de Derechos Económicos, Sociales y Culturales, firmados por Cuba en 2008, consagrar sus derechos en la Constitución y dar a los tratados de derechos humanos rango constitucional y aplicación directa.',null,59),('amparo-y-garantias','derechos','Amparo, hábeas corpus y hábeas data al alcance de cualquier persona','Un recurso de amparo oral, público, rápido, gratuito y sin formalidades, que cualquier persona pueda interponer para proteger todos sus derechos, junto al hábeas corpus contra la detención ilegal y el hábeas data para acceder a los propios datos personales.',null,60),('libertad-expresion','derechos','Libertad de expresión y de prensa, sin monopolios estatales','Reconocer y proteger la libertad de expresión, de información y de prensa, para que las personas, solas o en grupo, expresen sus ideas por cualquier medio, y desmontar el monopolio del Estado sobre la prensa y las comunicaciones.','Las fuentes coinciden en reconocer la libertad de expresión y de prensa. Difieren en las sanciones por sus abusos. Las dos posiciones proceden del mismo informe: la que excluye la cárcel en cualquier caso es el aporte de un participante; la que admite multas y privación de libertad en casos graves es el criterio de la comisión que redactó su ley de medios. Se muestran las dos, cada una con su referencia.',61),('libertad-reunion-asociacion','derechos','Libertad de reunión, manifestación y asociación','Todas las personas tienen derecho a reunirse, manifestarse pacíficamente y crear asociaciones políticas, civiles, económicas, culturales, sindicales, estudiantiles, religiosas o de cualquier otra índole, sin control de la administración pública.',null,62),('libertad-religiosa','derechos','Libertad religiosa y de conciencia','Reconocer el derecho de toda persona y de las instituciones religiosas a la libertad de conciencia y a profesar y practicar su religión en público y en privado.',null,63),('libre-movilidad','derechos','Libertad para entrar, salir y vivir donde se quiera','Todo cubano puede salir de su país y regresar libremente, sin perder su ciudadanía ni sus derechos por el tiempo que pase fuera, y fijar su residencia en cualquier lugar del territorio nacional.',null,64),('acceso-informacion-internet','derechos','Internet libre y acceso universal a la información','Garantizar el derecho universal a internet, libre y sin censura, para recibir y difundir información, y el acceso a las tecnologías de la información y a las frecuencias de radio y televisión.',null,65),('inviolabilidad-intimidad','derechos','Inviolabilidad del domicilio, las comunicaciones y los datos personales','Amparar a todos contra desalojos, detenciones, registros, confiscaciones o agresiones arbitrarias y contra la violación de la correspondencia y las comunicaciones, y prohibir el uso de datos personales o familiares sin autorización o sin orden judicial.',null,66),('igualdad-y-no-discriminacion','derechos','Igualdad de derechos y oportunidades, sin discriminación','Una sociedad sin castas privilegiadas ni grupos marginados, sin discriminación por motivos de raza, ideología, sexo, religión o edad, con los mismos derechos y oportunidades para todos y atención a los grupos históricamente marginados.',null,67),('derechos-extranjeros','derechos','Derechos de los extranjeros residentes','Equiparar a los extranjeros residentes con los ciudadanos en la protección de sus personas y bienes y en el disfrute de los derechos, e incluirlos de forma progresiva en los derechos políticos según su tiempo de residencia.',null,68),('diaspora-derechos-plenos','derechos','Plenos derechos para los cubanos que viven fuera','Restituir la condición plena de cubanos a todos los emigrados y exiliados y a sus hijos, con los mismos derechos que quienes viven en la isla, eliminar la categoría de «salida definitiva» y garantizar su derecho a regresar a vivir en Cuba.',null,69),('debido-proceso','derechos','Debido proceso: presunción de inocencia y abogado desde la detención','Garantizar la presunción de inocencia, también ante la policía y los medios, el derecho a un abogado desde el momento de la detención y asistencia jurídica gratuita, con jueces imparciales.',null,70),('pena-muerte','derechos','Abolir la pena de muerte','Abolir total e irrevocablemente la pena de muerte, sin excepción.',null,71),('despenalizar-conductas','derechos','Despenalizar conductas que no deben ser delito','Eliminar las normas que castigan como delito conductas que no son punibles, como el sacrificio de ganado mayor.',null,72),('reduccion-poblacion-penal','derechos','Reducir la población penal','Reducir la excesiva población penal cubana.',null,73),('derechos-no-nacido','derechos','Derechos patrimoniales del no nacido','Proteger los derechos patrimoniales y de otro tipo del concebido y aún no nacido como si ya hubiera nacido.',null,74),('derecho-aborto','derechos','Derecho a interrumpir el embarazo','Reconocer el derecho de la mujer a interrumpir su embarazo en una institución de salud, con políticas educativas para reducir el número de abortos sin limitar ese derecho.',null,75),('vida-desde-la-concepcion','derechos','Derecho a la vida desde su inicio hasta su fin natural','Reconocer el derecho a la vida desde su inicio hasta su fin natural.','La fuente no detalla sus consecuencias sobre el aborto o la eutanasia.',76),('elecciones-libres','sistema_electoral','Elecciones libres, plurales y con observación internacional','Celebrar elecciones libres, justas, plurales y competitivas, con voto universal, directo y secreto, bajo la supervisión de observadores nacionales e internacionales, para todos los cargos de autoridad.',null,77),('pluripartidismo','sistema_electoral','Pluripartidismo: libertad para formar partidos y competir en igualdad','Reconocer en la Constitución el derecho de todos los ciudadanos a formar partidos y competir lealmente en elecciones limpias, en igualdad de condiciones y sin privilegios para ningún grupo o corriente ideológica: una democracia representativa pluripartidista, gobierno de la mayoría con respeto a la minoría.',null,78),('ley-partidos','sistema_electoral','Ley de partidos que prohíba métodos violentos, no ideologías','Aprobar una Ley de Partidos Políticos que regule su creación, funcionamiento y financiamiento y vede el acceso al poder a quienes usen métodos violentos o antidemocráticos: no prohibir ideologías, sino estrategias y conductas que promuevan el odio, la destrucción de las instituciones, el racismo o la xenofobia.',null,79),('nueva-ley-electoral','sistema_electoral','Una nueva ley electoral antes de las primeras elecciones','Aprobar una nueva ley electoral, provisional si hace falta, que garantice que las primeras elecciones sean competitivas, transparentes y pluripartidistas, y convocar después elecciones libres.',null,80),('reformas-electorales-2019','sistema_electoral','Reformas electorales mínimas dentro de la Constitución de 2019','Dialogar sobre reformas electorales mínimas pero imprescindibles dentro del marco de la Constitución de 2019, a partir de las sugerencias del profesor Jorge I. Domínguez.',null,81),('autoridad-electoral-independiente','sistema_electoral','Autoridad electoral independiente y permanente','Crear un órgano electoral independiente, permanente y descentralizado, con el registro de electores a su cargo, que dirija los procesos electorales con acompañamiento internacional, tras la renuncia de los actuales directivos.',null,82),('candidaturas-libres','sistema_electoral','Que cualquier ciudadano pueda ser candidato, sin comisiones de candidatura','Reconocer el derecho de todo ciudadano a postularse a cualquier cargo electivo, en representación de un movimiento, partido o asociación, y eliminar las comisiones de candidatura y las asambleas de nominación.',null,83),('eleccion-diputados','sistema_electoral','Diputados elegidos por voto directo en distritos','Elegir a los diputados por voto directo y secreto de la ciudadanía, uno por distrito electoral de hasta sesenta mil habitantes, por mayoría absoluta.',null,84),('voto-emigracion','sistema_electoral','Derecho a votar de los cubanos que viven fuera','Que voten todos los ciudadanos con derechos civiles y políticos, vivan dentro o fuera de la isla.',null,85),('financiamiento-politico','sistema_electoral','Financiamiento electoral limpio y transparente','Financiar las campañas con fondos públicos asignados por el parlamento en proporción a la representación de cada partido, y con fondos privados de origen demostrable y con tope a las donaciones.',null,86),('cambio-de-modelo','modelo_pais','Cambio integral del modelo económico, social y político','Solo un cambio de modelo económico, social y político, basado en el respeto a las libertades individuales, puede sacar a Cuba del colapso: una transición económica y política que permita diseñar y aplicar un plan de reconstrucción, y que la sociedad y la economía dejen de usarse para ejercer el control.',null,87),('bienestar-universal','modelo_pais','Acceso universal al bienestar','Garantizar el acceso universal al bienestar: educación de calidad, salud integral con prevención, pensiones y seguridad social sostenibles, protección a las personas vulnerables, política ambiental basada en la ciencia y una defensa civil ante catástrofes.',null,88),('transparencia','modelo_pais','Cuentas públicas abiertas y Tribunal de Cuentas independiente','Que todas las finanzas del Estado sean de conocimiento público, con acceso gratuito y sin trabas a la información pública, declaración de bienes e ingresos de cada funcionario al empezar y terminar su cargo, y un Tribunal de Cuentas independiente que las fiscalice.',null,89),('funcion-publica-profesional','modelo_pais','Funcionarios por mérito, al servicio de la República y no de un partido','Que los funcionarios públicos sirvan a los intereses generales de la República y no a un partido, escogidos por méritos comprobados y con estabilidad en el cargo.',null,90),('reforma-del-estado','modelo_pais','Un Estado capaz, con reglas claras y rendición de cuentas','Reformar el Estado para que sea capaz de cumplir sus funciones económicas, técnicas, administrativas y políticas, con reglas claras, servicios básicos eficientes y mecanismos de participación y rendición de cuentas.',null,91),('gobierno-digital','modelo_pais','Gobierno digital y ventanilla única','Una plataforma digital de gobierno accesible a toda hora y un sistema único de registros con ventanilla única, para hacer trámites, firmar peticiones y acceder a datos públicos, respetando la privacidad.',null,92),('autonomia-municipal','modelo_pais','Autonomía real de los municipios','Reconocer la plena autonomía municipal en lo político, administrativo, normativo, económico y participativo, con una Ley de Municipios que dé a las comunidades capacidad real de gestionar su bienestar sin perder la unidad nacional.',null,93),('descentralizacion','modelo_pais','Provincias y municipios autónomos: máxima descentralización','Organizar el territorio en provincias y municipios autónomos, con personalidad jurídica y atribuciones propias, y descentralizar la administración a favor de las estructuras locales, poniendo fin al tutelaje partidista.',null,94),('fuerzas-seguridad-civiles','modelo_pais','Fuerzas armadas y policía neutrales, bajo autoridad civil','Fuerzas armadas profesionales y políticamente neutrales, y cuerpos policiales de carácter civil, dirigidos por ministros civiles y sometidos a la Constitución, que garanticen la centralidad de los derechos humanos.',null,95),('reduccion-fuerzas-armadas','modelo_pais','Desmilitarizar y reducir el gasto militar a favor de lo social','Desmilitarizar el país y reducir drásticamente los efectivos y recursos de las Fuerzas Armadas y del Ministerio del Interior, destinando ese gasto a seguridad social, educación, salud, alimentación y servicios comunitarios.',null,96),('servicio-militar-voluntario','modelo_pais','Servicio militar voluntario y objeción de conciencia','Abolir el Servicio Militar Obligatorio y regular un servicio militar voluntario.',null,97),('seguridad-ciudadana','modelo_pais','Prevenir las drogas y el crimen organizado','Prevenir y combatir la producción, el tráfico y el consumo de drogas y las asociaciones para delinquir.',null,98),('politica-exterior','modelo_pais','Política exterior de paz, derechos humanos y cooperación','Una política exterior al servicio de los desafíos nacionales, basada en la paz, la solución negociada de los conflictos, la defensa de los derechos humanos y la cooperación.',null,99),('reinsercion-internacional','modelo_pais','Volver a los organismos regionales e internacionales','Reinsertar a Cuba en todos los mecanismos de integración regional y global que sean democráticos y respeten los derechos humanos —OEA, ONU y sus agencias, FMI, Banco Mundial, BID— y cumplir los acuerdos internacionales.',null,100),('diversificacion-relaciones','modelo_pais','Relaciones diversificadas, sin depender de ninguna potencia','Diversificar las relaciones diplomáticas, comerciales y de cooperación con todas las naciones, sin depender de ninguna nación o bloque en particular.',null,101),('comunidad-regional','modelo_pais','Una comunidad latinoamericana y caribeña con instituciones propias','Impulsar una comunidad regional latinoamericana y caribeña, a partir de la CELAC, con instituciones y autoridades propias, sin llegar a ser un superestado.',null,102),('leyes-complementarias','modelo_pais','Un paquete de leyes para las reformas estructurales','Preparar un paquete coherente de leyes complementarias, unas 45 en una primera etapa, que dé marco jurídico y legitimidad a las reformas que Cuba necesita.',null,103),('plan-de-emergencia','reconstruccion','Plan de emergencia económica y humanitaria al inicio de la transición','Al comenzar la transición, aplicar un plan económico de emergencia contra el caos y el hambre, y atender de inmediato las necesidades de agua, saneamiento, salud, vivienda y educación, con ayuda internacional.',null,104),('energia','reconstruccion','Abrir el sector energético a la inversión privada','Liberalizar la importación y distribución de combustible por actores no estatales y crear un programa de generación eléctrica distribuida con inversión privada y mixta, con contratos y garantías que atraigan capital sin financiamiento público.',null,105),('infraestructura','reconstruccion','Inversión en infraestructura y empleo','Promover la inversión en carreteras, ferrocarriles, puertos, zonas económicas especiales, logística, telecomunicaciones, tecnología, energía solar y eólica y manufactura ligera, generando empleo en esos sectores.',null,106),('atraer-inversion','reconstruccion','Liberalizar la inversión y dar seguridad jurídica a los inversores','Liberalizar la inversión en todos los sectores, sin más límites que los de la ley, con un plan de recuperación creíble, seguridad jurídica, protección de la propiedad, reglas fiscales estables y acceso al crédito.',null,107),('financiamiento-internacional','reconstruccion','Ingresar en las instituciones financieras internacionales','Incorporar a Cuba al FMI, al Banco Mundial y a otros organismos financieros y comerciales internacionales, aunque sea primero como observador, para acceder a créditos ventajosos y mejorar su posición crediticia.',null,108),('deuda-externa','reconstruccion','Renegociar la deuda externa','Renegociar las deudas con el Club de París, el Club de Londres, Rusia y los demás acreedores, proponiendo un calendario de pagos extendido.',null,109),('reclamaciones-propiedad','reconstruccion','Resolver las reclamaciones por propiedades confiscadas','Negociar las reclamaciones por las confiscaciones a estadounidenses y a cubanos con procesos transparentes y sin tratos preferenciales, buscando una justicia restaurativa, distributiva y compasiva.','El inciso sobre las viviendas es el más sensible: la propia fuente reconoce que solo sería viable si los antiguos dueños lo aceptan.',110),('diaspora-en-la-economia','reconstruccion','La diáspora como inversora y socia de la recuperación','Incorporar a los emigrados cubanos a la economía como fuente de experiencia, capital, inversiones y acceso a mercados, y permitir que todo nacido en Cuba invierta en empresas medianas y grandes, resida donde resida.',null,111),('gaesa','reconstruccion','Intervenir y desmontar GAESA','Intervenir el conglomerado militar GAESA, tomar el control de su estructura empresarial y de sus recursos financieros dentro y fuera de la isla, y poner fin a su control de la economía.',null,112),('fin-planificacion-central','economia','Fin de la planificación centralizada: el mercado y el sector privado como motor','Acabar con la planificación hipercentralizada de la economía, eliminar de la Constitución «la dirección planificada de la economía», dar autonomía a todas las formas de propiedad y no temerle al mercado, con el sector privado como eje.','Casi todas estas propuestas proceden de economistas citados por la prensa.',113),('economia-social-mercado','economia','Economía social de mercado','Una economía de mercado con responsabilidad social, que proteja la propiedad privada y la inversión y garantice tanto mercado y libre contratación como sea posible y tanto control social y estatal como sea necesario, con el trabajo decente en el centro.',null,114),('socialismo-democratico','economia','Socialismo democrático y participativo, con propiedad común','Un modelo de socialismo democrático, participativo y de soberanía popular, que preserve un núcleo no capitalista en la economía y la política y dé más peso a la propiedad común junto a la privada.',null,115),('libertad-empresa','economia','Libertad de empresa para todos los cubanos','Garantizar el derecho de los cubanos a crear empresas privadas, individuales o cooperativas, a hacer negocios y a comerciar dentro y fuera del país, con libertad de gestión económica y de ejercicio profesional.',null,116),('propiedad-privada','economia','Derecho a la propiedad privada, con expropiación solo por juicio e indemnización','Reconocer plenamente el derecho a la propiedad privada de cubanos y extranjeros, con un marco jurídico estable, y permitir la expropiación solo por interés público, con indemnización y mediante procedimiento judicial.',null,117),('pluralidad-propiedad','economia','Economía plural: pública, privada, cooperativa y mixta','Una economía plural en la que participen todas las formas de propiedad: empresas públicas, cooperativas y sociales, privadas y mixtas.',null,118),('igualdad-economica-cubanos','economia','Los cubanos, con los mismos derechos económicos que los extranjeros','Permitir que todos los cubanos, residan o no en la isla, inviertan su capital, tengan empresas y se asocien con capital extranjero, poniendo fin a privilegios económicos que hoy solo tienen los extranjeros.',null,119),('reducir-propiedad-estatal','economia','Privatización transparente y Estado limitado a sectores estratégicos','Limitar la propiedad estatal a los sectores estratégicos, que también podrán gestionar empresas privadas, y privatizar de forma abierta y transparente empresas y activos estatales, incluida la tierra productiva.',null,120),('empresas-publicas-autonomas','economia','Empresas públicas gestionadas sin injerencia política','Que las empresas públicas no las administre el gobierno, sino juntas de directores o fideicomisos independientes de la política, guiados por la rentabilidad, la eficiencia y la productividad.',null,121),('competencia-antimonopolio','economia','Competencia y lucha contra los monopolios, estatales y privados','Evitar y regular los monopolios económicos, comerciales y financieros, estatales o privados, y penalizar los carteles y prácticas que dañen a los consumidores y supriman la competencia.',null,122),('emprendimiento','economia','Apoyo a las pymes y al trabajo por cuenta propia','Proteger y promover las pequeñas y medianas empresas y apoyar a quienes empiezan a trabajar por cuenta propia con ayuda para materias primas y facilidades de pago.',null,123),('comercio-exterior-libre','economia','Libertad de importar y exportar','Libertad de importación y exportación para todas las empresas y personas.',null,124),('economia-abierta','economia','Economía abierta e integrada al comercio internacional','Institucionalizar una economía abierta que aproveche la posición geográfica de Cuba para el transporte marítimo y el comercio, con acuerdos de libre comercio con el T-MEC, el CARICOM, el Mercosur, la Unión Europea y otros bloques.',null,125),('codigo-comercio-consumidor','economia','Código de Comercio y protección del consumidor','Un Código de Comercio basado en la libertad comercial, la licitud, la transparencia y la responsabilidad social y ambiental, y una ley que proteja al consumidor de abusos, fraudes y estafas.',null,126),('sistema-financiero','economia','Banca privada y un sistema financiero plural y supervisado','Permitir la banca privada y fomentar instituciones financieras públicas, sociales y privadas que den crédito a empresas, personas y organizaciones, con una supervisión bancaria efectiva.',null,127),('bolsa-de-valores','economia','Reabrir la Bolsa de La Habana','Reabrir la bolsa de valores de La Habana, que existió en los años cincuenta, con reglas, transparencia y auditoría, incluida la emisión local de bonos de la República.',null,128),('estabilizacion-monetaria','economia','Estabilizar el peso: convertibilidad y un solo mercado de divisas','Estabilizar la moneda nacional con plena convertibilidad del peso, un mercado de divisas unificado con tasa de cambio flexible y un sistema de pagos conectado con los bancos extranjeros.',null,129),('sistema-impositivo','economia','Impuestos progresivos que estimulen la producción','Un sistema de impuestos proporcionales y progresivos sobre las ganancias de todas las personas jurídicas y naturales, públicas o privadas, a partir de un ingreso básico exento, que estimule la producción y redistribuya la riqueza.',null,130),('subsidios','economia','Dejar atrás los subsidios generalizados a la energía','Trasladar a la economía los costos reales de la energía y sustituir los subsidios generalizados.','Las tres fórmulas proceden de economistas citados por la prensa y difieren sobre todo en el ritmo y en cómo proteger a los hogares vulnerables.',131),('derechos-laborales','trabajo','Derechos laborales según los convenios de la OIT','Incorporar a la Constitución y a un nuevo Código del Trabajo todos los derechos de los trabajadores reconocidos en los convenios de la Organización Internacional del Trabajo.',null,132),('libertad-sindical','trabajo','Sindicatos libres, convenio colectivo y derecho a huelga','Restituir a los trabajadores la libertad sindical plena: crear sindicatos independientes, negociar convenios colectivos y ejercer el derecho a huelga.',null,133),('seguridad-social','trabajo','Seguridad social para todos los riesgos de la vida','Una seguridad social que cubra vejez, discapacidad, muerte, enfermedad, maternidad, riesgos laborales y desempleo, y que garantice protección a todas las personas mayores, en especial a quienes están solas.',null,134),('empleo-juvenil','trabajo','Liberar empleos para los jóvenes ocupados por jubilados con doble salario','Que los jubilados de las Fuerzas Armadas y del Ministerio del Interior que cobran pensión y un segundo salario dejen esos puestos a ciudadanos menores de 35 años.',null,135),('salud-universal','salud','Salud universal, gratuita en la atención primaria y de urgencia','Un sistema de salud ético, universal, accesible y de calidad, que prevenga, cure y proteja, con atención primaria y de emergencia gratuita para todas las personas.',null,136),('salud-mixta','salud','Sanidad pública, privada y mixta','Combinar un sistema de salud público, privado y mixto, y reconocer el derecho a ejercer la medicina de forma privada.',null,137),('educacion-de-calidad','educacion','Educación universal de calidad','Una educación universal con altos estándares científicos, técnicos, humanistas y éticos, que integre ciencias, matemáticas, informática, inteligencia artificial y humanidades, y forme a la persona en lo intelectual y en lo cívico.',null,138),('autonomia-universitaria','educacion','Autonomía universitaria y libertad de cátedra','Devolver la autonomía a las universidades y restablecer la libertad de cátedra.',null,139),('educacion-civica','educacion','Educación cívica y en derechos humanos en todas las escuelas','Crear cátedras de educación ética y cívica y enseñar los derechos humanos —incluidos los del niño, la familia y la naturaleza— en todos los niveles, en los medios y en las instituciones cívicas y religiosas.',null,140),('libertad-educativa','educacion','Derecho de los padres a elegir la educación de sus hijos','Reconocer el derecho prioritario de los padres a elegir el tipo de educación, los valores y las creencias en que se forman sus hijos.',null,141),('formacion-juridica','educacion','Formación democrática de jueces, fiscales y abogados','Crear escuelas judiciales independientes y renovar las facultades de Derecho según los sistemas democráticos más avanzados, con cursos de ética y jurisprudencia internacional para jueces, fiscales y abogados formados en el sistema actual.',null,142),('proteccion-ambiental','medio_ambiente','Protección jurídica del medio ambiente y del patrimonio','Dar al medio ambiente la protección jurídica que merece, tomar medidas urgentes para su seguridad y para rescatar el patrimonio nacional, y garantizar el desarrollo sostenible para las generaciones futuras.',null,143),('derecho-al-agua','medio_ambiente','Derecho al agua','Reconocer el derecho al agua.',null,144),('matriz-energetica-renovable','medio_ambiente','Energía mayoritariamente renovable','Regular y propiciar una matriz energética en la que predominen cada vez más las fuentes renovables.',null,145),('derechos-animales','animales','Derechos de los animales usados en el turismo','Reconocer los derechos de los animales destinados a la actividad turística.',null,146),('biodiversidad','animales','Proteger las especies, los ecosistemas marinos y los parques naturales','Salvar especies animales y vegetales de la depredación causada por el crecimiento económico, con una Ley de Parques Naturales, y preservar especies, playas y paisajes marinos.',null,147),('sociedad-civil-fuerte','sociedad_civil','Una sociedad civil autónoma y fuerte','Institucionalizar una sociedad civil autónoma, democrática y pluralista, cuyo empoderamiento sea pilar de la democracia y del sostenimiento de las instituciones.',null,148),('participacion-ciudadana','sociedad_civil','Participación ciudadana directa en las leyes y las políticas públicas','Regular la participación directa de la ciudadanía en la elaboración de las leyes y de las políticas públicas, desde el municipio hasta el nivel nacional, para que la democracia sea lo más participativa posible.',null,149),('participacion-local','sociedad_civil','Presupuestos participativos y referendos locales','Presupuestos participativos vinculantes, referendos locales obligatorios para las decisiones clave y revocatoria de mandatos por petición ciudadana.',null,150),('proteccion-familia','familia','Protección jurídica de la familia','Proteger jurídicamente a la familia en todas sus formas: matrimonio, relaciones entre padres e hijos, madres solas, familias numerosas, personas mayores, alimentos, adopción y tutela.',null,151),('union-mismo-sexo','familia','Matrimonio entre personas del mismo sexo, con derecho a adoptar','Reconocer el matrimonio entre personas del mismo sexo con los mismos derechos que las parejas heterosexuales, incluido el derecho a la adopción.',null,152),('atencion-vulnerables','tercera_edad','Atención a las personas vulnerables','Un fondo y servicios para proteger a las personas vulnerables: niños sin amparo, personas mayores, personas con discapacidad, maternidad e infancia, y quienes viven en la calle.',null,153),('vivienda','vivienda','Derecho a una vivienda digna, con libre compraventa','Reconocer el derecho a una vivienda digna, autorizar la compraventa de viviendas sin limitaciones e incentivar la construcción privada, cooperativa y pública.',null,154),('igualdad-de-genero','genero','Igualdad de género y paridad','Reconocer el derecho a la igualdad de género.',null,155),('violencia-genero','genero','Ley contra la violencia de género y el abuso de menores','Prevenir y condenar la violencia contra las mujeres y el abuso de menores, incluida la violencia sexual, con una ley contra la violencia de género.',null,156),('derecho-alimentacion','alimentacion','Derecho a la alimentación y soberanía alimentaria','Reconocer el derecho a una alimentación sana, suficiente y balanceada y lograr la soberanía alimentaria con la recuperación ecológica de las tierras.',null,157),('tierra-para-quien-la-trabaja','alimentacion','La tierra, en propiedad de quien la trabaja','Entregar la tierra en propiedad a quienes la trabajan y distribuir su acceso de forma justa, con derecho de herencia y arrendamiento y sin latifundios.',null,158),('libertad-agricola','alimentacion','Liberar la agricultura y reabrir los mercados campesinos','Liberalizar el sector agrícola, hoy con la mayor parte de la tierra en manos del Estado, y reabrir los mercados libres campesinos para estimular la producción y reducir la escasez.',null,159),('estatuto-juridico-animales','animales','Que los animales dejen de ser cosas ante la ley','Reformar el Código Civil para reconocer a los animales como seres dotados de sensibilidad, con una categoría jurídica propia, y acompañar ese reconocimiento de la reforma de las normas procesales y de garantía para que tenga efectos reales.',null,1000),('defensoria-proteccion-animal','animales','Una Defensoría Nacional de Protección Animal, independiente y con poder de litigar','Crear un órgano público de defensa de los animales, separado de los organismos encargados de la producción ganadera, pesquera y comercial, con recursos y poderes propios para inspeccionar, actuar y acudir a los tribunales.',null,1000),('costa-adaptacion-climatica','medio_ambiente','Planificar la costa antes de que el mar la gane','Anticipar el retroceso costero en lugar de esperarlo: reasentamiento planificado y compensado de los asentamientos en riesgo, protección y restauración de manglares y dunas como defensa natural, y datos del monitoreo costero abiertos a la ciudadanía.',null,1000),('agua-reduccion-fugas-bombeo-solar','medio_ambiente','Agua: reparar lo que se pierde y desacoplar el bombeo de los apagones','Un programa nacional de reducción de fugas antes que nuevas obras de captación, bombeo solar autónomo en las estaciones críticas para que el agua no dependa de la red eléctrica, y una meta pública y verificable de tratamiento de aguas residuales.',null,1000),('residuos-servicio-exigible','medio_ambiente','La recogida de residuos como servicio básico exigible, no como campaña','Tratar la recogida y el tratamiento de la basura como un servicio básico permanente y exigible, con separación en origen y aprovechamiento de la fracción orgánica, en lugar de campañas periódicas cuyo efecto dura semanas.',null,1000),('informacion-ambiental-abierta','medio_ambiente','Medir el ambiente en público: datos abiertos de agua, aire y suelos','Monitoreo público, continuo y auditable del agua, el aire y los suelos, con acceso ciudadano a los datos en formato abierto y publicación íntegra de los estudios de impacto ambiental de toda obra pública. No se puede reparar lo que no se ha medido.',null,1000),('bienestar-animal-granjas-traccion','animales','Condiciones verificables en granjas, mataderos y animales de trabajo','Estándares auditables y exigibles para los animales usados en la producción de alimentos y como fuerza de trabajo, con supervisión veterinaria y alternativas económicas para quienes dependen de esa actividad.',null,1000),('transicion-espectaculos-experimentacion','animales','Transición ordenada fuera de peleas, exhibición y experimentación con animales','Sustituir de forma planificada las prácticas que infligen sufrimiento evitable -peleas, exhibición en zoológicos y experimentación- por alternativas sin animales, con reconversión de quienes viven de ellas.',null,1000),('sustitucion-materiales-traccion','animales','Sustitución gradual de la tracción y los materiales de origen animal','Programas voluntarios y progresivos para reemplazar el trabajo animal y los materiales de origen animal por alternativas asequibles, evaluadas por coste, durabilidad e impacto ambiental.',null,1000),('impacto-personas-animales-entorno','modelo_pais','Evaluar el impacto sobre personas, animales y entorno antes de aprobar una política','Que toda decisión pública se oriente a producir el mayor beneficio posible con el menor daño posible para personas, animales y entorno, y que cada propuesta pase una evaluación de impacto en esas tres dimensiones antes de deliberarse.',null,1000),('comites-deliberativos-sorteo','sociedad_civil','Comités deliberativos con ciudadanos elegidos por sorteo','Que las políticas públicas se evalúen en comités deliberativos formados a partes iguales por especialistas, ciudadanos elegidos por sorteo y representantes de los grupos afectados, que hacen recomendaciones fundamentadas al parlamento.',null,1000),('evaluacion-independiente-politicas','modelo_pais','Un órgano independiente que mida si las políticas funcionan','Crear un órgano constitucional autónomo que mida los resultados reales de las políticas aplicadas, audite el desempeño de los funcionarios y publique sus informes para el parlamento y la ciudadanía.',null,1000),('revision-continua-politicas','modelo_pais','Ninguna política es permanente: revisarla cuando los datos lo justifiquen','Que toda política pública pueda revisarse, mejorarse o sustituirse cuando los indicadores muestren malos resultados, aparezca un daño no previsto o surjan nuevas evidencias, tecnologías o ideas que den mejores resultados con menor daño.',null,1000),('ejecutivo-tecnico-no-partidista','constitucion','Un ejecutivo técnico y no partidista, elegido por concurso público','Que el Poder Ejecutivo sea un órgano técnico y no partidista que aplique las políticas aprobadas, con integrantes seleccionados por concurso público y evaluados por su desempeño, mientras los partidos compiten por el parlamento.',null,1000),('enfriamiento-puertas-giratorias','modelo_pais','Tres años sin trabajar en el sector sobre el que se decidió','Que quienes hayan ejercido cargos en el ejecutivo esperen al menos tres años antes de aceptar trabajos remunerados en sectores directamente relacionados con las decisiones que tomaron.',null,1000),('proteccion-denunciantes','modelo_pais','Protección para quien denuncia la corrupción','Proteger frente a cualquier represalia a quien denuncie de buena fe irregularidades, corrupción o violaciones de la Constitución cometidas por funcionarios, e investigar toda denuncia fundamentada en un máximo de noventa días.',null,1000),('ia-asesora-no-decide','derechos','La inteligencia artificial asesora, no decide','Que ninguna decisión que afecte derechos de personas, animales o entorno pueda adoptarse solo por un sistema algorítmico, sin validación humana documentada.',null,1000),('generaciones-futuras','medio_ambiente','Evaluar las decisiones a diez, veinticinco y cincuenta años','Evaluar las decisiones con efectos a largo plazo en horizontes de diez, veinticinco y cincuenta años, y que ninguna decisión comprometa de forma irreversible las condiciones de vida de quienes aún no han nacido.',null,1000),('accion-ciudadana-colectiva','derechos','Cualquier ciudadano puede ir a los tribunales en defensa del ambiente, los animales o la probidad pública','Que cualquier ciudadano pueda actuar ante los tribunales en defensa de intereses colectivos: derechos ambientales, bienestar animal, probidad pública o integridad de los procesos de decisión.',null,1000),('emergencia-caduca','constitucion','Las medidas de emergencia caducan a los sesenta días','Que las medidas urgentes adoptadas en una emergencia declarada valgan como máximo sesenta días, en los que el parlamento las confirma, modifica o anula; las que no se confirman expiran solas.',null,1000),('voto-delegable','sociedad_civil','Voto delegable y revocable en temas concretos','Permitir delegar el voto, de forma revocable, en personas de confianza para materias concretas en las decisiones de la plataforma de participación ciudadana.',null,1000),('financiamiento-solo-publico','sistema_electoral','Partidos y campañas financiados solo con fondos públicos','Que el financiamiento político sea exclusivamente público y proporcional, sin fondos del exterior y sin uso de recursos del Estado en beneficio de un partido.',null,1000),('estado-neutral-juramento','constitucion','Un Estado ideológicamente neutral, con juramento público de neutralidad','Que el Estado sea ideológicamente neutral en su estructura y funcionamiento, y que toda persona que asuma una función pública suscriba un juramento público de neutralidad e imparcialidad política e ideológica, verificable y auditado.',null,1000),('parlamento-mixto-sorteo','constitucion','Un parlamento mixto: representantes electos y ciudadanos elegidos por sorteo','Una Asamblea Nacional formada en un sesenta por ciento por representantes electos por sufragio directo, en un treinta por ciento por ciudadanos sorteados del padrón con mandato de dos años y en un diez por ciento por voces técnicas sin voto.',null,1000),('candidaturas-independientes-plataforma-plural','sistema_electoral','Candidaturas independientes comprometidas con una plataforma plural','Que quienes no militan en ningún partido puedan respaldar y presentar candidaturas independientes comprometidas públicamente a gobernar con una plataforma plural, construida con las propuestas ciudadanas y de organizaciones que la ciudadanía haya comparado y priorizado.',null,1000) on conflict do nothing;